(function() {
  document.addEventListener('DOMContentLoaded', () => {
    fetch('/feeds/posts/default?alt=json&max-results=5')
      .then(r => r.json())
      .then(data => {
        const ticker = document.getElementById('ticker-content');
        const posts = data.feed.entry || [];
        if (posts.length > 0 && ticker) {
          let items = posts.map(p =>
            `<a class="text-white text-decoration-none mx-3" href="${p.link.find(l => l.rel === 'alternate').href}">${p.title.$t}</a>`
          ).join(' • ');
          ticker.innerHTML = `<marquee scrollamount="4" onmouseover="this.stop();" onmouseout="this.start();">${items}</marquee>`;
        }
      })
      .catch(e => console.warn('Ticker feed error:', e));
  });
})();
